    saveConfig();
    JsonDocument ack;
    ack["type"] = "ack"; ack["for"] = "tuning_save"; ack["ok"] = true;
    wsSend(ack);
    logToBackend("info", "lidar config saved to LittleFS");

  } else if (!strcmp(type, "tuning_reset")) {
    resetConfig();
    JsonDocument ack;
    ack["type"] = "ack"; ack["for"] = "tuning_reset"; ack["ok"] = true;
    wsSend(ack);
    logToBackend("info", "lidar config reset to defaults");
  }
}

void sendHello() {
  JsonDocument doc;
  doc["type"]   = "hello";
  doc["device"] = "nodemcu_lidar";
  doc["fw"]     = "1.0.0";
  doc["ip"]     = WiFi.localIP().toString();
  JsonObject cfg = doc["config"].to<JsonObject>();
  cfg["lidar_min_range_mm"] = config.lidar_min_range_mm;
  cfg["lidar_max_range_mm"] = config.lidar_max_range_mm;
  cfg["min_quality"]        = config.min_quality;
  JsonArray arr = cfg["lidar_angle_filter"].to<JsonArray>();
  for (uint8_t i = 0; i < MAX_ANGLE_MASKS; i++) {
    if (!config.masks[i].active) continue;
    JsonObject m = arr.add<JsonObject>();
    m["start_deg"] = config.masks[i].start_deg;
    m["end_deg"]   = config.masks[i].end_deg;
  }
  wsSend(doc);
}

void onWsEvent(WStype_t type, uint8_t* payload, size_t len) {
  switch (type) {
    case WStype_CONNECTED:
      wsConnected = true;
      sendHello();
      break;
    case WStype_DISCONNECTED:
      wsConnected = false;
      break;
    case WStype_TEXT:
      handleMessage((const char*)payload, len);
      break;
    default:
      break;
  }
}

// ---------------------------------------------------------------------------
// LIDAR driver
// ---------------------------------------------------------------------------
void lidarSendCommand(uint8_t cmd) {
  uint8_t buf[2] = { RP_SYNC, cmd };
  Serial.write(buf, 2);
  Serial.flush();
}

void lidarStop() {
  lidarSendCommand(RP_CMD_STOP);
  delay(20);
  while (Serial.available()) Serial.read();
}

bool lidarStartScan() {
  lidarStop();
  lidarSendCommand(RP_CMD_RESET);
  delay(800);                                  // A1 needs ~800 ms after reset
  while (Serial.available()) Serial.read();

  lidarSendCommand(RP_CMD_SCAN);

  // Consume the 7-byte response descriptor: A5 5A 05 00 00 40 81
  uint32_t deadline = millis() + 1000;
  uint8_t got = 0;
  while (got < RESP_DESCRIPTOR_LEN && millis() < deadline) {
    if (Serial.available()) { Serial.read(); got++; }
    else yield();
  }
  return got == RESP_DESCRIPTOR_LEN;
}

// Per-revolution accumulation buffers.
uint16_t sampleCount = 0;
float    angles[MAX_SAMPLES];
uint16_t dists[MAX_SAMPLES];
uint8_t  quals[MAX_SAMPLES];

uint16_t droppedThisRev = 0;
uint32_t revStartMs     = 0;
uint32_t revCounter     = 0;

// Smallest in-range return of the revolution — the backend forwards this to
// the Arduino so collision-stop can act on it (§10 collision_stop_distance_mm).
uint16_t minDistThisRev = 0xFFFF;

void publishRevolution() {
  if (!wsConnected) { sampleCount = 0; droppedThisRev = 0; return; }

  uint32_t now  = millis();
  uint32_t dtMs = (revStartMs == 0) ? 0 : (now - revStartMs);
  revStartMs = now;

  // Compact numeric arrays keep the frame small; the ESP8266 has ~40 KB of
  // usable heap and one frame per revolution at 5.5 Hz must not fragment it.
  JsonDocument doc;
  doc["type"]     = "scan";
  doc["seq"]      = revCounter++;
  doc["t_ms"]     = now;
  doc["rev_ms"]   = dtMs;
  doc["n"]        = sampleCount;
  doc["dropped"]  = droppedThisRev;
  doc["min_range_mm"] = config.lidar_min_range_mm;
  doc["max_range_mm"] = config.lidar_max_range_mm;
  if (minDistThisRev != 0xFFFF) doc["min_distance_mm"] = minDistThisRev;

  JsonArray aArr = doc["angles_deg"].to<JsonArray>();
  JsonArray dArr = doc["dists_mm"].to<JsonArray>();
  JsonArray qArr = doc["quality"].to<JsonArray>();
  for (uint16_t i = 0; i < sampleCount; i++) {
    aArr.add(angles[i]);
    dArr.add(dists[i]);
    qArr.add(quals[i]);
  }

  String out;
  out.reserve(sampleCount * 16 + 200);
  serializeJson(doc, out);
  ws.sendTXT(out);

  sampleCount    = 0;
  droppedThisRev = 0;
  minDistThisRev = 0xFFFF;
}

// 5-byte packet: [S !S Q(6)] [Aq[6:0] C=1] [Aq[14:7]] [Dist_L] [Dist_H]
uint8_t  pktBuf[5];
uint8_t  pktIdx = 0;
bool     synced = false;

void processPacket() {
  uint8_t b0 = pktBuf[0];
  uint8_t startFlag    = b0 & 0x01;
  uint8_t invStartFlag = (b0 >> 1) & 0x01;
  uint8_t quality      = b0 >> 2;

  // The check bit of byte 1 must be 1 on a valid packet.
  if ((pktBuf[1] & 0x01) != 0x01) { synced = false; return; }
  if (startFlag == invStartFlag)  { synced = false; return; }

  float    angleDeg = (float)(((uint16_t)(pktBuf[2]) << 7) | (pktBuf[1] >> 1)) / 64.0f;
  uint16_t distMm   = (uint16_t)((((uint16_t)pktBuf[4]) << 8) | pktBuf[3]) / 4;

  if (startFlag) publishRevolution();   // new revolution begins at this sample

  // --- filtering, from the live runtime config ---------------------------
  if (quality < config.min_quality)          return;
  if (distMm == 0)                           return;  // no valid return
  if (distMm < config.lidar_min_range_mm)    return;
  if (distMm > config.lidar_max_range_mm)    return;
  if (angleDeg < 0.0f || angleDeg >= 360.0f) return;
  if (angleMasked(angleDeg))                 return;

  if (distMm < minDistThisRev) minDistThisRev = distMm;

  if (sampleCount < MAX_SAMPLES) {
    angles[sampleCount] = angleDeg;
    dists[sampleCount]  = distMm;
    quals[sampleCount]  = quality;
    sampleCount++;
  } else {
    droppedThisRev++;
  }
}

void pumpLidar() {
  // Bounded per-call read so the WebSocket and WiFi stacks still get serviced.
  int budget = 256;
  while (Serial.available() && budget-- > 0) {
    uint8_t b = Serial.read();

    if (!synced) {
      // Resync: a start-of-revolution byte has S=1, !S=0 -> low bits 0b01.
      if ((b & 0x03) == 0x01) {
        pktBuf[0] = b;
        pktIdx = 1;
        synced = true;
      }
      continue;
    }

    pktBuf[pktIdx++] = b;
    if (pktIdx >= 5) {
      pktIdx = 0;
      processPacket();
      if (!synced) continue;            // processPacket dropped sync; resync
      // Stay synced: the next byte should be the start of the next packet.
      // We re-validate on every packet anyway, so no extra work here.
      synced = true;
      // Peek-free approach: assume stream alignment holds until a packet fails
      // validation, at which point processPacket() clears `synced`.
      pktIdx = 0;
      // Read the next byte as pktBuf[0] on the following iteration.
      // Flip to "collecting" state by pre-loading nothing.
      // (Handled by the branch below.)
      collecting = true;
    }
  }
}

// ---------------------------------------------------------------------------
uint32_t lastLidarRestartMs = 0;
uint32_t lastSampleSeenMs   = 0;

void setup() {
  // UART is the LIDAR link, not a debug console. 115200 8N1 per §3.
  Serial.begin(LIDAR_BAUD);
  Serial.setRxBufferSize(1024);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  uint32_t deadline = millis() + 15000;
  while (WiFi.status() != WL_CONNECTED && millis() < deadline) {
    delay(200);
  }

  LittleFS.begin();
  loadConfig();

  ws.begin(BACKEND_HOST, BACKEND_PORT, BACKEND_PATH);
  ws.onEvent(onWsEvent);
  ws.setReconnectInterval(2000);

  lidarStartScan();
  lastLidarRestartMs = millis();
  lastSampleSeenMs   = millis();
  revStartMs         = millis();
}

void loop() {
  ws.loop();

  if (WiFi.status() != WL_CONNECTED) {
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    delay(200);
    return;
  }

  uint16_t before = sampleCount;
  pumpLidar();
  if (sampleCount != before) lastSampleSeenMs = millis();

  // If the LIDAR stops producing samples for 3 s, re-issue SCAN. A1 units
  // occasionally need this after a brown-out on the shared 5 V rail.
  if (millis() - lastSampleSeenMs > 3000 &&
      millis() - lastLidarRestartMs > 5000) {
    logToBackend("warn", "no lidar samples for 3 s — restarting scan");
    synced = false;
    pktIdx = 0;
    lidarStartScan();
    lastLidarRestartMs = millis();
    lastSampleSeenMs   = millis();
  }
}

