/* SLAM Bot UI — dark-first, single stylesheet, no framework.
   Colours are chosen for the one thing that matters on a robot dashboard:
   connection/run state must be readable at a glance and distinguishable
   without relying on hue alone (each state also has a distinct label). */

:root {
  --bg: #0d1117;
  --bg-panel: #151b23;
  --bg-panel-2: #1c232c;
  --bg-input: #0b0f14;
  --border: #2a3441;
  --border-bright: #3d4a5c;

  --text: #e6edf3;
  --text-dim: #9aa7b4;
  --text-faint: #6b7684;

  --accent: #4f9cf9;
  --accent-dim: #2f6fbf;

  --ok: #3fb950;
  --ok-bg: #12261a;
  --warn: #d29922;
  --warn-bg: #2a2113;
  --err: #f85149;
  --err-bg: #2d1517;

  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --radius: 8px;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* --- layout ------------------------------------------------------------ */
.app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  height: 52px;
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.brand {
  font-weight: 650;
  font-size: 15px;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.brand span {
  color: var(--accent);
}

.nav {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  flex: 1;
}

.nav a {
  padding: 6px 12px;
  border-radius: var(--radius);
  color: var(--text-dim);
