  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.grid {
  display: grid;
  gap: 14px;
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
}

.row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.spacer {
  flex: 1;
}

/* --- status indicators ------------------------------------------------- */
.dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--text-faint);
}

.dot.ok {
  background: var(--ok);
  box-shadow: 0 0 8px rgba(63, 185, 80, 0.5);
}

.dot.err {
  background: var(--err);
}

.dot.warn {
  background: var(--warn);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 12px;
  background: var(--bg-panel-2);
  border: 1px solid var(--border);
  white-space: nowrap;
}

.chip.ok {
  background: var(--ok-bg);
  border-color: var(--ok);
  color: var(--ok);
}

.chip.warn {
  background: var(--warn-bg);
  border-color: var(--warn);
  color: var(--warn);
}

.chip.err {
  background: var(--err-bg);
  border-color: var(--err);
  color: var(--err);
}

/* --- stat tiles -------------------------------------------------------- */
.stat {
  background: var(--bg-panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 12px;
}

.stat-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-faint);
  margin-bottom: 3px;
}

.stat-value {
  font-family: var(--mono);
  font-size: 19px;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.stat-unit {
  font-size: 12px;
  color: var(--text-dim);
  margin-left: 3px;
}

.stat-sub {
  font-size: 11px;
  color: var(--text-faint);
  margin-top: 2px;
  font-family: var(--mono);
}

/* --- buttons ----------------------------------------------------------- */
button {
  font: inherit;
  padding: 7px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--border-bright);
  background: var(--bg-panel-2);
  color: var(--text);
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, opacity 0.12s;
}

button:hover:not(:disabled) {
  background: var(--border);
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

button.primary {
  background: var(--accent-dim);
  border-color: var(--accent);
  color: #fff;
  font-weight: 600;
}

button.primary:hover:not(:disabled) {
  background: var(--accent);
}

button.success {
  background: #16351f;
  border-color: var(--ok);
  color: var(--ok);
  font-weight: 600;
}

button.success:hover:not(:disabled) {
