}

button.danger:hover:not(:disabled) {
  background: #52201f;
}

button.estop {
  background: var(--err);
  border-color: #ff6b63;
  color: #fff;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 9px 18px;
}

button.estop:hover:not(:disabled) {
  background: #ff6b63;
}

button.sm {
  padding: 4px 9px;
  font-size: 12px;
}

button.toggle.on {
  background: var(--accent-dim);
  border-color: var(--accent);
  color: #fff;
}

/* --- forms ------------------------------------------------------------- */
input[type='text'],
input[type='number'],
select,
textarea {
  font: inherit;
  background: var(--bg-input);
  color: var(--text);
