}

/* --- tuning ------------------------------------------------------------ */
.param {
  padding: 11px 0;
  border-bottom: 1px solid var(--border);
}

.param:last-child {
  border-bottom: none;
}

.param-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 6px;
}

.param-name {
  font-weight: 600;
  font-size: 13px;
}

.param-key {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-faint);
}

.param-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.param-controls input[type='range'] {
  flex: 1;
  min-width: 100px;
}

.param-controls input[type='number'] {
  width: 92px;
  font-family: var(--mono);
  text-align: right;
}

.param-help {
  font-size: 12px;
  color: var(--text-faint);
  margin-top: 5px;
}

.badge {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 650;
}

.badge.unsaved {
  background: var(--warn-bg);
  color: var(--warn);
  border: 1px solid var(--warn);
}

.badge.measure {
  background: #2a1f2e;
  color: #d2a8ff;
  border: 1px solid #8957e5;
}

.badge.target {
  background: var(--bg-input);
  color: var(--text-faint);
  border: 1px solid var(--border);
  font-family: var(--mono);
  text-transform: none;
}

