  font-size: 12px;
  max-height: calc(100vh - 260px);
  overflow-y: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-input);
}

.log-line {
  display: flex;
  gap: 9px;
  padding: 3px 10px;
  border-bottom: 1px solid rgba(42, 52, 65, 0.5);
  align-items: baseline;
}

.log-line:hover {
  background: rgba(79, 156, 249, 0.06);
}

.log-time {
  color: var(--text-faint);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.log-source {
  flex-shrink: 0;
  width: 58px;
  color: var(--accent);
}

.log-level {
  flex-shrink: 0;
  width: 44px;
  text-transform: uppercase;
  font-size: 10px;
  font-weight: 700;
}

.log-level.info {
  color: var(--text-dim);
}

.log-level.warn {
  color: var(--warn);
}

.log-level.error {
  color: var(--err);
}

.log-msg {
  word-break: break-word;
  white-space: pre-wrap;
}

.log-line.warn {
  background: rgba(210, 153, 34, 0.06);
}

.log-line.error {
  background: rgba(248, 81, 73, 0.08);
}

/* --- console output (flash center) ------------------------------------ */
.console {
  font-family: var(--mono);
  font-size: 12px;
  background: #06090d;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 12px;
  height: 340px;
  overflow-y: auto;
  white-space: pre-wrap;
  word-break: break-word;
}

.console .stderr {
  color: #ffa198;
}

.console .stdout {
  color: var(--text-dim);
}

.console .meta {
  color: var(--accent);
  font-weight: 600;
}

/* --- canvas ------------------------------------------------------------ */
.canvas-wrap {
  position: relative;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.canvas-wrap canvas {
  display: block;
  width: 100%;
  touch-action: none;
}

.canvas-overlay {
  position: absolute;
  top: 8px;
  left: 10px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
  pointer-events: none;
  text-shadow: 0 1px 3px #000;
  line-height: 1.6;
}

/* --- chat -------------------------------------------------------------- */
.chat {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 460px;
  overflow-y: auto;
  padding: 4px;
}

.msg {
  padding: 9px 12px;
  border-radius: var(--radius);
  max-width: 84%;
  white-space: pre-wrap;
  word-break: break-word;
}

.msg.user {
  align-self: flex-end;
  background: var(--accent-dim);
  color: #fff;
}

.msg.bot {
  align-self: flex-start;
  background: var(--bg-panel-2);
  border: 1px solid var(--border);
}

.msg.error {
  align-self: flex-start;
  background: var(--err-bg);
  border: 1px solid var(--err);
  color: #ffa198;
}

/* --- suggestions ------------------------------------------------------- */
.suggestion {
  background: var(--bg-panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 11px 13px;
  margin-bottom: 9px;
}

.suggestion-head {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  margin-bottom: 5px;
}

.suggestion-param {
  font-family: var(--mono);
  font-weight: 650;
  color: var(--accent);
}

.suggestion-delta {
  font-family: var(--mono);
  font-size: 12px;
}

.suggestion-why {
  font-size: 12px;
  color: var(--text-dim);
}

/* --- misc -------------------------------------------------------------- */
.mono {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
}

.dim {
  color: var(--text-dim);
}

.faint {
  color: var(--text-faint);
}

.small {
  font-size: 12px;
}

.notice {
  padding: 10px 13px;
  border-radius: var(--radius);
  font-size: 13px;
  border: 1px solid var(--border);
  background: var(--bg-panel-2);
  margin-bottom: 12px;
}

.notice.warn {
  background: var(--warn-bg);
  border-color: var(--warn);
}

.notice.err {
  background: var(--err-bg);
  border-color: var(--err);
}

.notice.info {
  background: rgba(79, 156, 249, 0.08);
  border-color: var(--accent-dim);
}

.notice strong {
  display: block;
  margin-bottom: 3px;
}

table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

table.data th,
table.data td {
  text-align: left;
  padding: 6px 9px;
  border-bottom: 1px solid var(--border);
}

table.data th {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-faint);
  font-weight: 650;
}

table.data td.num {
  font-family: var(--mono);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.dpad {
  display: grid;
  grid-template-columns: repeat(3, 62px);
  grid-template-rows: repeat(3, 48px);
  gap: 6px;
}

.dpad button {
  padding: 0;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dpad .stop-cell {
  font-size: 12px;
  font-weight: 700;
}

.empty {
  padding: 36px 20px;
  text-align: center;
  color: var(--text-faint);
  font-size: 13px;
}

.scroll-x {
  overflow-x: auto;
}

@media (max-width: 640px) {
  .topbar {
    height: auto;
    flex-wrap: wrap;
    padding: 8px 12px;
    gap: 8px;
  }
  .content {
    padding: 12px;
  }
}

