      const fitScale = Math.min(cssWidth / mapWidthM, height / mapHeightM) * 0.94
      const scale = fitScale * view.zoom
      const offsetX = (cssWidth - mapWidthM * scale) / 2 + view.panX
      const offsetY = (height - mapHeightM * scale) / 2 + view.panY

