                  : 'Send this goal to Nav2'
              }
            >
              Send to Nav2
            </button>
            <button className="sm" onClick={() => setGoalHint(null)}>
              Cancel
            </button>
            {controlMode !== 'nav2' && (
              <span className="small warn faint">
                Control mode is Manual — switch to Nav2 on the Dashboard to
                accept goals.
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

