  font-size: 12.5px;
  color: var(--text);
  word-break: break-all;
}

.cmd button {
  flex-shrink: 0;
}

.rules {
  margin: 0;
  padding-left: 20px;
  color: var(--text-dim);
}

.rules li {
  margin-bottom: 7px;
}

.rules li strong {
  color: var(--text);
}

.step {
  display: flex;
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
}

.step:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.step-n {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 13px;
}

.step-body {
  flex: 1;
  min-width: 0;
}

.step-title {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-weight: 650;
  font-size: 14.5px;
  margin-bottom: 8px;
}

.step-body p:first-of-type {
  margin-top: 0;
}

/* Pin tags: colour-coded by signal class, but each also carries its own
   border weight so they stay distinguishable without relying on hue. */
.pin-tag {
  display: inline-block;
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--bg-input);
  border: 1px solid var(--border-bright);
  white-space: nowrap;
}

.pin-tag.signal {
  color: #4f9cf9;
  border-color: #2f6fbf;
}

.pin-tag.encoder {
  color: #3fb950;
  border-color: #2a7a38;
}

.pin-tag.uart {
  color: #a371f7;
  border-color: #6f42c1;
}

.pin-tag.v5 {
  color: #ff9f4a;
  border-color: #b56a24;
}

.pin-tag.vbat {
  color: #f85149;
  border-color: #a33;
}

.pin-tag.gnd {
  color: #8b98a5;
  border-color: #5c6b7d;
}

.pin-tag.wifi {
  color: var(--text-faint);
  border-style: dashed;
}

/* --- applications ------------------------------------------------------ */
.app-card {
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
}

.app-card:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

/* --- presentation mode ------------------------------------------------- */
.deck {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: var(--bg);
  display: flex;
  flex-direction: column;
}

.deck-stage {
  flex: 1;
  overflow-y: auto;
  padding: 48px 8vw;
  max-width: 1400px;
  width: 100%;
  margin: 0 auto;
}

.slide-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 60vh;
}

.slide-h1 {
  font-size: clamp(34px, 6vw, 60px);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin: 0;
}

.slide-h2 {
  font-size: clamp(22px, 3.4vw, 34px);
  font-weight: 680;
  letter-spacing: -0.02em;
  margin: 0 0 4px;
}

.slide-lead {
  font-size: clamp(15px, 1.8vw, 19px);
  color: var(--text-dim);
  max-width: 62ch;
  line-height: 1.55;
}

.deck-stage .stat-value {
  font-size: 22px;
}

.deck-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  background: var(--bg-panel);
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

.deck-progress {
  height: 3px;
  background: var(--bg-panel-2);
  flex-shrink: 0;
}

.deck-progress-fill {
  height: 100%;
  background: var(--accent);
  transition: width 0.22s ease;
}

@media (max-width: 640px) {
  .topbar {
    height: auto;
    flex-wrap: wrap;
    padding: 8px 12px;
    gap: 8px;
  }
  .content {
    padding: 12px;
  }
  .deck-stage {
    padding: 24px 20px;
  }
  .step {
    gap: 10px;
  }
}

