  int end = i;
  while (end < (int)req.length() &&
         (isdigit(req[end]) || req[end] == '-')) end++;
  if (end == i) return fallback;
  return req.substring(i, end).toInt();
}

void sendJson(WiFiClient& c) {
  String body = String("{\"armed\":") + (armed ? "true" : "false") +
                ",\"el\":" + String(encLeft) +
                ",\"er\":" + String(encRight) + "}";
  c.print(F("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n"
            "Cache-Control: no-store\r\nConnection: close\r\nContent-Length: "));
  c.print(body.length());
  c.print(F("\r\n\r\n"));
  c.print(body);
}

void handleClient(WiFiClient& client) {
  String line = client.readStringUntil('\n');
  // Drain the rest of the request headers so the browser doesn't see a reset.
  while (client.available()) {
    String h = client.readStringUntil('\n');
    if (h.length() <= 1) break;
  }

  if (line.startsWith("GET /c?")) {
    int l = queryInt(line, "l=", 0);
    int t = queryInt(line, "t=", 0);
    drive(l, t);
    sendJson(client);

  } else if (line.startsWith("GET /arm?")) {
    armed = queryInt(line, "v=", 0) != 0;
