// ---------------------------------------------------------------------------
// Tiny HTTP handling
// ---------------------------------------------------------------------------
long queryInt(const String& req, const char* key, long fallback) {
  int i = req.indexOf(key);
  if (i < 0) return fallback;
  i += strlen(key);
  int end = i;
  while (end < (int)req.length() &&
         (isdigit(req[end]) || req[end] == '-')) end++;
  if (end == i) return fallback;
  return req.substring(i, end).toInt();
}

