void writeMotor(int pinIn1, int pinIn2, int duty) {
  duty = constrain(duty, -config.max_pwm_duty, config.max_pwm_duty);
  if (duty >= 0) {
    analogWrite(pinIn1, duty);
    analogWrite(pinIn2, 0);
  } else {
    analogWrite(pinIn1, 0);
    analogWrite(pinIn2, -duty);
  }
}

